node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get compatible products
const compatIds = ['PROD-FA0948','PROD-2DBA15','PROD-7C0240','PROD-73FAB4'];
const placeholders = compatIds.map(() => '?').join(',');
const compatible = db.prepare('SELECT * FROM products WHERE product_id IN (' + placeholders + ')').all(...compatIds);
console.log('Compatible products:', JSON.stringify(compatible, null, 2));

// Also search for other audio products
const audio = db.prepare(\"SELECT * FROM products WHERE subcategory = 'audio' AND product_id != 'PROD-B98D14'\").all();
console.log('Other audio products:', JSON.stringify(audio, null, 2));
"

